#include <iostream>
#include <vector>
#include <string>
#include <queue>
using namespace std;

int main() {
    string s;
    cin >> s;

    int count[26] = {0};
    queue<char> candidates;
    string out;
    for (char ch : s) {
        count[ch - 'a']++;
        if (count[ch - 'a'] == 1) candidates.push(ch);
        while (!candidates.empty() && count[candidates.front() - 'a'] > 1) candidates.pop();
        out += candidates.empty() ? '#' : candidates.front();
    }
    cout << out << "\n";

    return 0;
}

